/* ---------- small builders ---------- */
const logoSvg=(sz)=>`<svg viewBox="0 0 52 52" style="width:${sz}px;height:${sz}px" aria-label="로고 자리표시"><rect x="2" y="2" width="48" height="48" fill="none" stroke="currentColor" stroke-width="2" stroke-dasharray="5 4"/><circle cx="26" cy="26" r="14" fill="var(--ac)"/><rect x="24" y="6" width="4" height="40" fill="var(--bg)"/></svg>`;
const person=(c,sz)=>`<svg viewBox="0 0 64 64" style="width:${sz||48}px;height:${sz||48}px" aria-hidden="true"><circle cx="32" cy="21" r="10" fill="${c}" stroke="var(--ln)" stroke-width="1.5"/><path d="M8 63c0-17 10-25 24-25s24 8 24 25z" fill="${c}" stroke="var(--ln)" stroke-width="1.5"/></svg>`;
const body=(c,c2)=>`<svg viewBox="0 0 200 420" style="width:100%;height:100%" aria-hidden="true"><ellipse cx="100" cy="404" rx="70" ry="9" fill="#000" opacity=".35"/><circle cx="100" cy="52" r="30" fill="${c2||c}" stroke="var(--ln)" stroke-width="2"/><path d="M62 28q38-34 76 0l-4 12H66z" fill="${c}" stroke="var(--ln)" stroke-width="2"/><path d="M60 100h80l14 120-18 6-8-70-6 130H92l-4-130-8 70-18-6z" fill="${c}" stroke="var(--ln)" stroke-width="2"/><path d="M80 224h40l8 170h-24l-4-120-4 120H72z" fill="${c}" stroke="var(--ln)" stroke-width="2" opacity=".92"/><rect x="60" y="160" width="80" height="10" fill="var(--ac)"/></svg>`;
U.person=person;
const hint=(k,l)=>`<span class="hint"><kbd>${k}</kbd>${l}</span>`;
const hdr=(right)=>`<header class="top"><div class="logo">${logoSvg(52)}<div><div class="nm">[게임 이름]</div><div class="sub">STEADY TO VIVID STUDIO</div></div></div><div class="rw g16">${right||''}</div></header>`;
const acct=()=>`<span class="chip">${person('#6f8f7a',22)} ${D.me}</span><span class="chip mono">핑 18 ms</span>`;
const ftr=(l,r)=>`<footer class="foot"><div>${l||''}</div><div class="mono">${r||'v0.1.0-dev · 자리표시 화면'}</div></footer>`;
const B=(label,o)=>{o=o||{};const a=[];
 a.push(`class="btn${o.pri?' pri':''}${o.dng?' dng':''}${o.sm?' sm2':''}"`);
 if(o.go)a.push(`data-go="${o.go}"`);if(o.act)a.push(`data-act="${o.act}"`);if(o.back)a.push('data-back');
 if(o.dis)a.push('disabled');if(o.af)a.push('data-af');a.push(`data-fid="${o.id||label}"`);if(o.st)a.push(`style="${o.st}"`);if(o.title)a.push(`title="${o.title}"`);
 return `<button ${a.join(' ')}>${o.ic?ICO[o.ic]:''}${label}${o.k?` <kbd>${o.k}</kbd>`:''}</button>`;};
U.B=B;
const S=(cur,k)=>(cur&&cur.set&&cur.set[k]!==undefined)?cur.set[k]:U.DEF[k];
const pct=(v,mn,mx)=>Math.round((v-mn)/(mx-mn)*100);
/* setting rows */
const rSld=(c,k,name,mn,mx,st,fmt,desc)=>{const v=S(c,k);return `<div class="row" data-desc="${desc}" data-dt="${name}"><label class="nm" for="s_${k}">${name}</label><div class="ct"><input id="s_${k}" type="range" data-k="${k}" min="${mn}" max="${mx}" step="${st}" value="${v}" style="--p:${pct(v,mn,mx)}%" aria-label="${name}"><span class="val" data-v="${k}" data-f="${fmt}">${fmtV(v,fmt)}</span></div></div>`;};
function fmtV(v,f){v=+v;return f==='%'?Math.round(v)+'%':f==='p'?Math.round(v*100)+'%':f==='d'?v.toFixed(2):f==='x'?v.toFixed(2)+'x':String(Math.round(v));}
const rTg=(c,k,name,desc)=>{const v=S(c,k);return `<div class="row" data-desc="${desc}" data-dt="${name}"><span class="nm" id="l_${k}">${name}</span><div class="ct"><button class="tg" role="switch" aria-checked="${!!v}" aria-labelledby="l_${k}" data-act="tg:${k}" data-fid="tg${k}"><span>${v?'켬':'끔'}</span></button></div></div>`;};
const rDd=(c,k,name,opts,desc)=>{const v=S(c,k);return `<div class="row" data-desc="${desc}" data-dt="${name}"><label class="nm" for="s_${k}">${name}</label><div class="ct"><select class="dd" id="s_${k}" data-k="${k}">${opts.map(o=>`<option${o.startsWith('English')?' disabled':''}${o===v?' selected':''}>${o}</option>`).join('')}</select></div></div>`;};
const rSeg=(c,k,name,opts,desc)=>{const v=S(c,k);return `<div class="row" data-desc="${desc}" data-dt="${name}"><span class="nm" id="l_${k}">${name}</span><div class="ct"><div class="seg" role="group" aria-labelledby="l_${k}">${opts.map(o=>`<button aria-pressed="${o===v}" data-act="seg:${k}:${o}" data-fid="seg${k}${o}">${o}</button>`).join('')}</div></div></div>`;};
const secH=(t)=>`<div class="lbl" style="padding:18px 20px 8px">${t}</div>`;
/* ---------- settings tabs ---------- */
function setGfx(c){return secH('화면')+rDd(c,'mode','화면 모드',['전체 화면','테두리 없는 창','창 모드'],'게임 창을 전체 화면, 테두리 없는 창, 창 모드 중 하나로 띄웁니다. 적용을 눌러야 바뀝니다.')
 +rDd(c,'res','해상도',['1920 × 1080','2560 × 1440','3024 × 1964','3840 × 2160'],'화면에 그리는 가로·세로 픽셀 수입니다. 모니터가 지원하는 크기만 고를 수 있습니다.')
 +rDd(c,'fps','인게임 FPS 제한',['무제한','60','120','144','240'],'초당 프레임 수의 상한입니다. 수직 동기화가 켜져 있으면 모니터 주사율을 따릅니다.')
 +rTg(c,'vsync','수직 동기화','화면 찢김을 없앱니다. 켜면 입력 지연이 조금 늘 수 있습니다.')
 +secH('화질')+rSeg(c,'preset','전반적인 그래픽 품질',['낮음','보통','높음','사용자 설정'],'아래 고급 항목을 한 번에 정합니다. 직접 바꾸면 사용자 설정이 됩니다.')
 +rSld(c,'bright','밝기',0,100,1,'i','화면 전체의 밝기입니다. 견본의 가장 어두운 칸이 겨우 보일 때가 알맞습니다.')
 +rSld(c,'rscale','렌더링 크기',50,100,5,'%','해상도 대비 실제로 그리는 크기입니다. 낮추면 프레임이 오르지만 화면이 흐려집니다.')
 +rSld(c,'fov','1인칭 시야 (FOV)',60,100,1,'i','1인칭 시점의 세로 시야각입니다. 넓히면 주변이 더 보이지만 먼 곳이 작아집니다.')
 +secH('고급 (사용자 설정)')+rDd(c,'aa','안티 앨리어싱',['끔','FXAA','SMAA'],'물체 가장자리의 계단 현상을 줄입니다.')
 +rDd(c,'shadow','그림자',['끔','낮음','보통','높음'],'그림자가 그려지는 거리와 선명도입니다.')
 +rDd(c,'tex','텍스처',['낮음','보통','높음'],'표면 그림의 해상도입니다. 낮추면 그래픽 메모리를 덜 씁니다.')
 +rDd(c,'fx','이펙트',['낮음','높음'],'총구 화염, 연기, 오염 안개 같은 효과의 양입니다.')
 +rDd(c,'dist','거리 보기',['낮음','보통','높음','울트라'],'카메라가 그리는 최대 거리입니다. 50명 매치에서는 높음 이하를 권장합니다.')
 +rTg(c,'ao','앰비언트 오클루전','구석과 틈에 은은한 그늘을 넣어 입체감을 줍니다.');}
function setAud(c){return secH('음량')+rSld(c,'vm','전체 음량',0,100,1,'%','게임의 모든 소리에 곱해지는 음량입니다.')
 +rSld(c,'vfx','효과음',0,100,1,'%','총성, 발소리, 재장전, 폭발 같은 전투 소리의 음량입니다.')
 +rSld(c,'vamb','환경음',0,100,1,'%','바람, 설비 소음, 가이거 계수관, 지역 경보 같은 주변 소리의 음량입니다.')
 +rSld(c,'vui','UI 소리',0,100,1,'%','명중·처치 확인음과 메뉴 소리의 음량입니다.')
 +secH('공간음향')+rDd(c,'dev','출력 방식',['헤드폰','스피커(스테레오)','스피커(5.1)'],'출력 장치에 맞춰 방향 표현을 조정합니다. 헤드폰을 권장합니다.')
 +rTg(c,'spatial','공간음향 (HRTF)','발소리와 총성의 방향·높이를 헤드폰에서 더 또렷하게 들려줍니다.')
 +rTg(c,'cue','소리 방향 표시 (시각 보조)','총성·발소리가 난 방향을 화면 가장자리에 표시합니다. 소리를 듣기 어려운 경우에 도움이 됩니다.')
 +`<div class="row" data-desc="들려오는 소리를 확인합니다." data-dt="소리 시험"><span class="nm">소리 시험</span><div class="ct">${B('발소리 재생',{sm:1,act:'toast:발소리 시험음을 재생했습니다.',id:'t1'})}${B('가이거 경보 재생',{sm:1,act:'toast:가이거 경보음을 재생했습니다.',id:'t2'})}</div></div>`;}
function setCtl(c){
 const keys=U.KEYS.map((k,i)=>{const id='k'+i,L=c&&c.listen===id;return `<div class="row" data-desc="바꿀 줄의 키를 누른 뒤 새 키를 누르면 바로 저장됩니다. Esc는 취소입니다." data-dt="${k[0]}" style="min-height:60px;padding:4px 16px"><span class="nm" style="width:230px;font-size:var(--fs-s)">${k[0]}</span><div class="ct"><button class="kbd${L?' listen':''}" style="min-width:128px;cursor:pointer" data-act="key:${id}" data-fid="${id}" aria-label="${k[0]} 키 변경, 현재 ${(c&&c.keys&&c.keys[id])||k[1]}">${L?'키를 누르세요':((c&&c.keys&&c.keys[id])||k[1])}</button><span class="kbd" style="min-width:90px;opacity:.75" aria-label="보조 키 ${k[2]}">${k[2]}</span></div></div>`;}).join('');
 return `<div class="rw" style="align-items:stretch;gap:0;height:100%"><div style="width:700px;flex:none;border-right:1px solid var(--ln)">${secH('마우스')}${rSld(c,'sens','마우스 감도',0.05,1.5,0.01,'d','마우스를 움직일 때 시점이 도는 빠르기입니다.')}${rSld(c,'s1','1배 조준 감도 (ADS)',0.2,1.5,0.01,'x','견착하거나 배율 없는 조준 사이트로 정조준할 때 마우스 감도에 곱해지는 값입니다.')}${rSld(c,'s2','2배 조준경 감도',0.2,1.5,0.01,'x','2배율 조준경을 볼 때 곱해지는 값입니다.')}${rSld(c,'s4','4배 조준경 감도',0.2,1.5,0.01,'x','4배율 조준경을 볼 때 곱해지는 값입니다.')}${rTg(c,'inv','마우스 상하 반전','마우스를 위로 밀면 시점이 아래로 내려가게 합니다.')}<div class="row" data-desc="모든 키를 처음 상태로 되돌립니다." data-dt="키 초기화"><span class="nm">키 설정</span><div class="ct">${B('키 모두 기본값으로',{sm:1,act:'keysreset',id:'kr'})}</div></div></div><div class="grow" style="overflow-y:auto;overflow-x:hidden;height:100%">${secH('키 설정 (주 키 · 보조 키)')}${keys}</div></div>`;}
function setPly(c){return secH('조준')+rSeg(c,'sight','정조준 방식',['탭 전환','꾹 누르기'],'탭 전환: 우클릭을 짧게 누를 때마다 정조준이 켜지고 꺼집니다. 꾹 누르기: 누르고 있는 동안만 정조준합니다.')
 +rSeg(c,'shoulder','견착 방식',['꾹 누르기','탭 전환'],'정조준 방식이 탭 전환일 때만 적용됩니다.')
 +rDd(c,'view','기본 시점',['3인칭','1인칭'],'매치를 시작할 때의 시점입니다. 경기 중에는 V 키로 바꿀 수 있습니다.')
 +rDd(c,'xh','조준선 색',['흰색','연두','하늘','노랑'],'배경에 묻히지 않는 색을 고르세요.')
 +rTg(c,'kill','킬 로그 표시','처치 기록을 화면 오른쪽 위에 표시합니다.')
 +secH('언어')+rDd(c,'lang','언어',['한국어','English (준비 중)'],'지금은 한국어만 지원합니다. 영어는 이후 업데이트에서 추가할 예정입니다.')
 +secH('접근성')+rSld(c,'uis','UI 크기',80,150,5,'%','메뉴와 HUD 글자·아이콘 크기를 키웁니다. 본문 기준 크기는 1080p에서 18px입니다.')
 +rDd(c,'cb','색약 보정',['끔','적색약','녹색약','청황색약'],'아군·적·오염 표시에 색과 함께 모양·문자를 항상 같이 씁니다. 보정은 색조만 바꿉니다.')
 +rTg(c,'cap','소리 자막','총성·경보·방송 소리를 짧은 문구로 화면에 보여 줍니다.')
 +rTg(c,'shake','화면 흔들림 줄이기','폭발·피격 때 카메라 흔들림을 줄입니다.')
 +rTg(c,'flash','깜빡임 줄이기','섬광탄·경보등의 밝은 깜빡임을 줄입니다.');}
