 /* ---- left top: compact pollution briefing ---- */
 const info=`<div class="pn col g8" style="padding:14px 16px;width:340px"><div class="rw g8"><span class="ac">${ICO.rad}</span><b>오염 현황 브리핑 · 청람도</b></div><div class="sm">6개 지역 모두 <b class="okc">✓ 안전</b> · 첫 경고 <b class="mono">05:00</b> 후</div><div style="display:grid;grid-template-columns:repeat(6,1fr);gap:4px" role="img" aria-label="6개 지역 모두 안전">${REG.map(r=>`<i style="height:10px;border:1px solid var(--ok);background:var(--acs)" title="${r[0]} 안전"></i>`).join('')}</div></div>`;
 /* ---- left bottom: the always-visible dock ---- */
 const tpp=`<div class="seg full" role="group" aria-label="시점">${[['3인칭','TPP 3인칭'],['1인칭','FPP 1인칭']].map(i=>`<button aria-pressed="${pv===i[0]}" data-act="pv:${i[0]}" data-fid="pv${i[0]}"${dis}>${member?ICO.lock+' ':''}${i[1]}</button>`).join('')}</div>`;
 const mdb=(isSolo)=>{const sel=isSolo===solo;return `<button class="mdb${sel?' sel':''}" role="radio" aria-checked="${sel}" data-act="mode:${isSolo?'solo':'squad'}" data-fid="mode${isSolo?'s':'q'}"${dis}>${people_icon(isSolo?1:4,30)}<b>${isSolo?'솔로':'스쿼드'}</b><span class="ms">${member?ICO.lock+' 잠김':(sel?'✓ 선택됨':(isSolo?'1명':'최대 4명'))}</span></button>`;};
 const modes=`<div class="rw g8" role="radiogroup" aria-label="모드" style="align-items:stretch">${mdb(true)}${mdb(false)}</div>`;
