const mdbN=(m,isSolo,cls)=>{const sel=isSolo===m.solo;return `<button class="mdb${sel?' sel':''}${cls?' '+cls:''}" role="radio" aria-checked="${sel}" data-act="mode:${isSolo?'solo':'squad'}" data-fid="mode${isSolo?'s':'q'}"${m.dis}>${people_icon(isSolo?1:4,cls==='h'?28:36)}<span class="mt"><b>${isSolo?'솔로':'스쿼드'}</b><span class="ms">${m.member?ICO.lock+' 잠김':(sel?'✓ 선택됨':(isSolo?'1명':'최대 4명'))}</span></span></button>`;};
const pvSegN=m=>`<div class="seg" role="group" aria-label="시점">${[['3인칭','TPP 3인칭'],['1인칭','FPP 1인칭']].map(i=>`<button aria-pressed="${m.pv===i[0]}" data-act="pv:${i[0]}" data-fid="pv${i[0]}"${m.dis}>${m.member?ICO.lock+' ':''}${i[1]}</button>`).join('')}</div>`;
const tagN=(p,m)=>{if(p.lead)return '<span class="st lead">★ 파티장</span>';const r=m.rd[p.id];const btn=m.proto&&!m.search&&((m.leader&&!p.me)||(m.member&&p.me));return btn?`<button class="btn sm2" data-act="rdy:${p.id}" data-fid="rdy${p.id}" title="프로토타입: 눌러서 준비 상태를 바꿉니다">${r?'✓ 준비 완료':'… 준비 중'}</button>`:`<span class="st ${r?'ready':'wait'}">${r?'✓ 준비 완료':'… 준비 중'}</span>`;};
const inviteBtn=(txt)=>B(txt||'+ 초대',{sm:1,act:'toast:초대 코드 CH-7K2Q를 복사했습니다.',id:'inv'});
/* big island map with region borders, 20 elevator platforms, key elevators, briefing */
const GATES=[[70,38,3],[100,70,4],[68,92,3],[160,42,3],[150,72,4],[160,98,3]];
const bigMap=(full)=>{let g='';const off=[[-12,-6],[8,-10],[16,6],[-6,12]];GATES.forEach(r=>{for(let k=0;k<r[2];k++)g+=`<rect x="${r[0]+off[k][0]}" y="${r[1]+off[k][1]}" width="4" height="4" fill="var(--ac)"/>`;});
 const lab=REG.map((r,i)=>`<text x="${GATES[i][0]}" y="${GATES[i][1]+(i===1||i===4?24:22)}" text-anchor="middle" font-size="5.2" font-weight="700" fill="var(--tx)">${r[0]}</text><text x="${GATES[i][0]}" y="${GATES[i][1]+(i===1||i===4?29.5:27.5)}" text-anchor="middle" font-size="4" fill="var(--ok)">✓ 안전 · 승강장 ${r[1]}</text>`).join('');
 return `<svg viewBox="0 0 240 130" preserveAspectRatio="${full?'xMidYMid slice':'xMidYMid meet'}" style="width:100%;height:100%;display:block" role="img" aria-label="청람도 지도: 6개 지역, 승강장 20곳, 열쇠 승강기 3곳"><rect width="240" height="130" fill="var(--sf)"/><g stroke="var(--ln)" stroke-width=".3" opacity=".6">${Array.from({length:12},(_,i)=>`<path d="M${i*20} 0V130"/>`).join('')}${Array.from({length:7},(_,i)=>`<path d="M0 ${i*20}H240"/>`).join('')}</g><path d="M26 74 L40 40 L86 22 L140 16 L196 30 L218 62 L204 100 L150 116 L90 112 L44 98Z" fill="var(--bg)" stroke="var(--tx)" stroke-width="1.1"/><g stroke="var(--ln)" stroke-width=".8" fill="none"><path d="M60 36 L100 62 L120 20M100 62 L70 100M100 62 L160 70 L200 40M160 70 L150 114"/></g><path d="M96 20 C88 44 112 56 98 76 S110 100 100 114" fill="none" stroke="var(--ac)" stroke-width="1.4" opacity=".85"/><g fill="var(--t2)"><path d="M54 52l7-12 7 12zM130 36l8-13 8 13zM186 56l6-10 6 10z"/></g>${g}${full?'':lab}<g fill="none" stroke="var(--wr)" stroke-width=".8">${[[88,52],[172,58],[120,100]].map(p=>`<path d="M${p[0]} ${p[1]-3.5}l3.5 3.5-3.5 3.5-3.5-3.5z"/>`).join('')}</g></svg>`;};
const lobby1=m=>{const party=m.party;
 const rail=party.map(p=>p.e?`<div class="rcard empty"><div class="rl">슬롯 ${party.indexOf(p)+1}</div><div class="col g8" style="align-items:center;justify-content:center;flex:1"><span style="font-size:34px;color:var(--t2)">+</span>${inviteBtn('+ 초대')}<span class="sm mut mono">CH-7K2Q</span></div></div>`:`<div class="rcard${p.me?' me':''}"><div class="rl">슬롯 ${party.indexOf(p)+1}${p.me?' · 나':''}</div><div class="rw g8">${person(p.c,40)}<div class="col" style="gap:0"><b style="font-size:24px">${p.n}</b><span class="sm mut">${p.role}</span></div></div><div style="margin-top:auto">${tagN(p,m)}</div></div>`).join('');
 return `${topbar('play','n')}
 <div class="abs pn" style="left:64px;top:118px;width:1120px;height:604px;overflow:hidden;z-index:2;padding:0">${bigMap()}<div class="abs pn col g8" style="left:16px;top:16px;width:372px;padding:12px 14px"><div class="rw g8"><span class="ac">${ICO.rad}</span><b>오염 브리핑</b><span class="badge okc" style="margin-left:auto">✓ 전 지역 안전</span></div><div class="sm">첫 경고 <b class="mono">05:00</b> 후 · 최종 지역은 매 판 무작위</div><div class="sm mut">${ICO.key} 열쇠 승강기 ◇ 3곳 · 팀이 함께 타야 작동</div></div><div class="abs sm mut" style="left:14px;bottom:10px;background:var(--pn);padding:4px 10px;border:1px solid var(--ln)"><span class="ac">■</span> 승강장 20곳 · <span class="wr">◇</span> 열쇠 승강기 · 청람도 2.4×2.0 km</div></div>
 <div class="abs col g8" style="left:64px;top:738px;width:1120px;z-index:2"><div class="rw" style="justify-content:space-between"><span class="lbl">승강기 대기 레일 · 승강기 B (4인승) ${m.solo?'· 솔로':''}</span><span class="chip mono">초대 코드 CH-7K2Q</span></div><div class="rail">${rail}</div>${reasonH(m)}</div>
 <aside class="abs ticket col g16" style="right:64px;top:118px;width:600px;bottom:44px;z-index:2" aria-label="투입 명령서"><div class="rw" style="justify-content:space-between"><div class="lbl">투입 명령서 · No.0716</div><span class="chip">${m.solo?'혼자':'파티 '+(m.party.filter(p=>!p.e).length)+'/4'}</span></div>${sumChip(m)}<div class="col g8"><div class="lbl">모드</div><div class="rw g8" role="radiogroup" aria-label="모드" style="align-items:stretch">${mdbN(m,true,'big')}${mdbN(m,false,'big')}</div></div><div class="rw" style="justify-content:space-between"><div class="lbl">시점</div>${pvSegN(m)}</div><div class="rw" style="justify-content:space-between"><div class="lbl">맵</div><span class="chip">${ICO.rad} 청람도 · 6개 지역 · 50명 · 약 20~25분</span></div>${fillBar(m)}<div class="card col g8" style="padding:12px 14px"><div class="lbl">오늘의 목표 · 지난 매치</div><div class="sm">오염 경고가 오기 전에 열쇠 1개 확보 · 지난 매치 <b>3위 · 4킬 · 17:42</b></div></div><div class="grow"></div><div class="col g8"><div class="lbl">서명란</div>${sBtn(m,84,30)}<div class="rw" style="justify-content:flex-end">${devBtn(m)}</div></div></aside>`;};
/* layout 2: elevator control panel */
const floorTiles=(m)=>{const xs=[640,820,1000,1180];let s='',o='';m.party.forEach((p,i)=>{const x=xs[i];const y=575;
  s+=`<g transform="translate(${x},${y})"><polygon points="-70,40 70,40 86,96 -86,96" fill="${p.e?'none':(m.rd[p.id]||p.lead?'var(--acs2)':'var(--bg)')}" stroke="${p.e?'var(--t2)':(p.lead?'var(--ac)':(m.rd[p.id]?'var(--ok)':'var(--wr)'))}" stroke-width="3"${p.e?' stroke-dasharray="8 6"':''}/>${p.e?'':`<text y="76" text-anchor="middle" font-size="24" font-weight="700" fill="${p.lead?'var(--ac)':(m.rd[p.id]?'var(--ok)':'var(--wr)')}" font-family="-apple-system,Apple SD Gothic Neo,sans-serif">${p.lead?'★ 파티장':(m.rd[p.id]?'✓ 준비 완료':'… 준비 중')}</text>`}</g>`;
  if(!p.e){const sc=p.me?1.25:1.05;s+=`<g transform="translate(${x},${y+30}) scale(${sc})"><ellipse rx="40" ry="8" fill="#000" opacity=".5"/><g fill="${p.c}" stroke="var(--ln)" stroke-width="2"><rect x="-13" y="-72" width="26" height="72" rx="4"/><rect x="-19" y="-142" width="38" height="74" rx="8"/><circle cx="0" cy="-160" r="16"/></g><rect x="-19" y="-118" width="38" height="7" fill="var(--ac)"/></g><text x="${x}" y="${y+122}" text-anchor="middle" font-size="22" font-weight="700" fill="var(--tx)" font-family="-apple-system,Apple SD Gothic Neo,sans-serif">${p.n}${p.me?' (나)':''}</text>`;}
  else s+=`<g transform="translate(${x},${y+30})"><g fill="none" stroke="var(--t2)" stroke-width="2" stroke-dasharray="6 5"><rect x="-13" y="-72" width="26" height="72" rx="4"/><rect x="-19" y="-142" width="38" height="74" rx="8"/><circle cx="0" cy="-160" r="16"/></g></g>`;
  if(p.e)o+=`<div style="position:absolute;left:${x-60}px;top:${y+104}px;width:120px"><button class="btn sm2" style="width:120px" data-act="toast:초대 코드 CH-7K2Q를 복사했습니다." data-fid="inv">+ 초대</button></div>`;
  else if(m.proto&&!m.search&&!p.lead&&((m.leader&&!p.me)||(m.member&&p.me)))o+=`<button class="tagbtn" style="left:${x-80}px;top:${y+44}px;width:160px;height:50px" data-act="rdy:${p.id}" data-fid="rdy${p.id}" aria-label="${p.n} 준비 상태 바꾸기 (프로토타입)"></button>`;});
 return [s,o];};
