const lobby5=m=>{const slots=m.party.map((p,i)=>p.e?`<div class="seat empty"><span class="mono mut">좌석 ${i+1}</span><span style="font-size:30px;color:var(--t2)">+</span>${inviteBtn('+ 초대')}</div>`:`<div class="seat${p.me?' me':''}"><span class="mono mut">좌석 ${i+1}${p.me?' · 나':''}</span>${person(p.c,44)}<b>${p.n}</b>${tagN(p,m)}</div>`).join('');
 return `${topbar('play','n')}<div class="abs bpass" style="left:300px;top:128px;width:1320px;height:800px;z-index:2" aria-label="탑승권">
 <div class="bp-main col g16"><div class="rw" style="justify-content:space-between"><div><div class="lbl">BOARDING PASS · 승강기 탑승권</div><div style="font:700 44px/1.1 var(--fh)">청람도 투입</div></div><div class="col" style="align-items:flex-end"><span class="lbl">승강장 (예시 · 투입 때 서버가 배정)</span><span class="mono b" style="font-size:44px">ELEV 07</span></div></div>${sumChip(m)}
 <div class="rw g24" style="align-items:flex-start"><div class="col g8 grow"><div class="lbl">모드</div><div class="rw g8" role="radiogroup" aria-label="모드" style="align-items:stretch">${mdbN(m,true)}${mdbN(m,false)}</div></div><div class="col g8"><div class="lbl">시점</div>${pvSegN(m)}<div class="lbl" style="margin-top:6px">맵</div><span class="chip">${ICO.rad} 청람도 · 6개 지역</span></div></div>
 <div class="lbl">탑승자 ${m.solo?'1':'4'}석 · 승강기 B</div><div class="rw g8" style="align-items:stretch">${slots}</div><div class="grow"></div>${reasonH(m)}</div>
 <div class="bp-cut" aria-hidden="true"></div>
 <div class="bp-stub col g16"><div class="lbl">STUB · 0716</div>${barcode}${fillBar(m)}<div class="grow"></div><div class="stamp">${sBtn(m,92,23)}</div><div class="rw" style="justify-content:flex-end">${devBtn(m)}</div></div></div>
 <div class="abs sm mut" style="left:0;right:0;bottom:30px;text-align:center;z-index:3">Enter 탑승 확인 · Esc 로비 · 투입 지역은 서버가 배정합니다</div>`;};
/* 6: full-screen map + minimal overlays */
const lobby6=m=>{const pref=(m.c&&m.c.pref!=null)?m.c.pref:0;const S8=8.31;
 const rg=REG.map((r,i)=>`<button class="rg${i===pref?' on':''}" aria-pressed="${i===pref}" style="left:${GATES[i][0]*S8-37}px;top:${GATES[i][1]*S8+40}px" data-act="pref:${i}" data-fid="pref${i}" title="희망 지역 (우선 고려, 보장 아님)"><b>${r[0]}</b><span class="sm">${i===pref?'★ 희망 · ':'✓ 안전 · '}승강장 ${r[1]}</span></button>`).join('');
 return `<div class="abs" style="inset:0;z-index:0">${bigMap(1)}</div><div class="abs" style="inset:0;z-index:0;background:linear-gradient(180deg,var(--bg) 0,transparent 22%,transparent 60%,var(--bg) 100%);opacity:.85"></div>${topbar('play','n')}
 <div class="abs rg-wrap" style="inset:0;z-index:1;pointer-events:none"><div style="pointer-events:auto">${rg}</div></div>
 <div class="abs col g8" style="left:48px;top:118px;z-index:3;width:520px">${sumChip(m)}<div class="rw g8" role="radiogroup" aria-label="모드" style="align-items:stretch">${mdbN(m,true,'h')}${mdbN(m,false,'h')}</div>${pvSegN(m)}</div>
 <div class="abs col g8" style="right:48px;top:118px;z-index:3;width:380px"><div class="lbl">파티 ${m.party.filter(p=>!p.e).length}/4 · CH-7K2Q</div>${m.party.map((p,i)=>partyChip(p,m,i)).join('')}</div>
 <div class="abs pn col g8" style="right:48px;top:420px;z-index:3;width:380px;padding:12px 14px"><div class="rw g8"><span class="ac">${ICO.rad}</span><b>오염 브리핑</b><span class="badge okc" style="margin-left:auto">✓ 전 지역 안전</span></div><div class="sm">첫 경고 <b class="mono">05:00</b> 후 · ${ICO.key} 열쇠 승강기 ◇ 3곳</div><div class="sm mut">희망 지역: <b style="color:var(--tx)">${REG[pref][0]}</b> (우선 고려, 보장 아님)</div></div>
 <div class="abs pn col g8" style="left:50%;transform:translateX(-50%);bottom:36px;width:660px;z-index:3;padding:14px 16px">${fillBar(m)}${reasonH(m)}<div class="rw g16">${sBtn(m,76,30)}${devBtn(m)}</div></div>
 <button class="drawer" style="left:48px;bottom:44px" data-act="toast:채팅 서랍은 대기 구역과 인게임에서 열립니다." data-fid="drawer">채팅 ▴ <span class="badge">1</span></button>`;};
