 const banner=`<div class="rw g24"><div class="stat"><div class="mono" style="font-size:120px;line-height:1;font-weight:800;color:var(--ac)">3<span style="font-size:48px">위</span></div></div><div><h1>탈락했습니다</h1><div class="mut">50명 중 3위 · 13팀 중 3위 · 우리 팀 9킬</div></div></div>`;
 const pol=`<div class="card col g8"><div class="rw g8 lbl">${ICO.rad} 오염 요약</div><div class="rw" style="justify-content:space-between"><span>오염 구역 노출</span><b class="mono">0:41</b></div><div class="rw" style="justify-content:space-between"><span>오염으로 받은 피해</span><b class="mono">38</b></div><div class="rw" style="justify-content:space-between"><span>마지막 위치</span><b>청람읍권 (안전 지역)</b></div></div>`;
 const key=`<div class="card col g8"><div class="rw g8 lbl">${ICO.key} 탈출·열쇠·부활 요약</div><div class="rw" style="justify-content:space-between"><span>열쇠 엘리베이터 사용</span><b class="mono">1회</b></div><div class="rw" style="justify-content:space-between"><span>최종 탈출 승강기</span><b>도달하지 못함</b></div><div class="rw" style="justify-content:space-between"><span>칩 부활 (받음 / 해 줌)</span><b class="mono">1 / 0</b></div><div class="rw" style="justify-content:space-between"><span>이동 지역</span><b>북령 산악 → 청람읍권</b></div></div>`;
